import json, sys
t = json.load(open(sys.argv[1], encoding='utf-8'))
rv = t.get('returnValue', t)
if isinstance(rv, str):
    rv = json.loads(rv)
if 'topo' in rv:
    rv = rv['topo']
    rv = rv.get('returnValue', rv)
for sc in ['emitterSpawnScript', 'emitterUpdateScript', 'particleSpawnScript', 'particleUpdateScript']:
    s = rv[sc]
    print('##', sc, {k: v for k, v in s.items() if not isinstance(v, (list, dict))})
    for m in s.get('modules', []):
        ins = m.get('inputs', [])
        meta = {k: v for k, v in m.items() if not isinstance(v, (list, dict))}
        print('  -', meta)
        for i in ins:
            print('      .', {k: v for k, v in i.items() if not isinstance(v, (list, dict))})
print(json.dumps(rv['renderers'])[:800])

