import json, sys
raw = json.load(open(sys.argv[1], encoding='utf-8'))
rv = raw['returnValue']
if isinstance(rv, str):
    rv = json.loads(rv)
json.dump(rv, open(sys.argv[1] + '.pretty.json', 'w'), indent=1)


def short(v):
    st = v.get('struct', {}).get('refPath', '').split('.')[-1]
    val = v.get('value', {})
    if 'Enum' in st:
        return 'ENUM ' + val.get('displayName', '') + ' [' + val.get('enumName', '') + ' @ ' + val.get('enum', {}).get('refPath', '') + ']'
    if 'Unsupported' in st:
        return None
    if 'DynamicInput' in st:
        return 'DYN ' + val.get('dynamicInputAsset', {}).get('refPath', '')
    if 'Linked' in st:
        return 'LINK ' + val.get('linkedVariable', {}).get('name', '')
    return st + ' ' + json.dumps(val)


vals = rv.get('vals')
if vals:
    vals = vals.get('returnValue', vals)
    mods = vals if isinstance(vals, list) else vals.get('modules', vals.get('moduleInputValues', []))
    if isinstance(mods, dict):
        print(list(mods.keys()))
    for m in mods:
        print('-', m.get('scriptName', ''), m.get('moduleName'))
        for i in m.get('inputs', []):
            s = short(i['value'])
            if s:
                print('    ', i['name'], '=', s[:200])
for k in rv:
    if k != 'vals':
        print('=====', k)
        print(json.dumps(rv[k])[:6000])

