import json
O = 'editor_toolset.toolsets.object.ObjectTools.'
M = 'editor_toolset.toolsets.material.MaterialTools.'
A = 'editor_toolset.toolsets.asset.AssetTools.'


def t(name, args):
    return execute_tool(name, json.dumps(args))


def sp(path, vals):
    return t(O + 'set_properties', {'instance': {'refPath': path}, 'values': json.dumps(vals)})


def add(mat, cls, x, y):
    return t(M + 'add_expression', {'material_or_function': {'refPath': mat}, 'expression_class': {'refPath': '/Script/Engine.' + cls}, 'x': x, 'y': y})['returnValue']['refPath']


def conn(a, ao, b, bi):
    t(M + 'connect_expressions', {'from_expression': {'refPath': a}, 'from_output_name': ao, 'to_expression': {'refPath': b}, 'to_input_name': bi})


def out(a, ao, prop):
    t(M + 'connect_to_output', {'expression': {'refPath': a}, 'output_name': ao, 'material_property': prop})


def make(name, soft):
    r = t(M + 'create_material', {'folder_path': '/Game/FX', 'asset_name': name})['returnValue']['refPath']
    sp(r, {'BlendMode': 'BLEND_Translucent', 'ShadingModel': 'MSM_Unlit', 'bUsedWithNiagaraSprites': True, 'bUsedWithNiagaraRibbons': True, 'TwoSided': True})
    pc = add(r, 'MaterialExpressionParticleColor', -600, 0)
    info = {'pc_out': t(M + 'get_expression_output_names', {'expression': {'refPath': pc}})['returnValue']}
    out(pc, '', 'MP_EmissiveColor')
    if soft:
        uv = add(r, 'MaterialExpressionTextureCoordinate', -900, 200)
        c2 = add(r, 'MaterialExpressionConstant2Vector', -900, 300)
        sp(c2, {'R': 0.5, 'G': 0.5})
        sm = add(r, 'MaterialExpressionSphereMask', -600, 200)
        sp(sm, {'AttenuationRadius': 0.5, 'HardnessPercent': 0.0})
        info['sm_in'] = t(M + 'get_expression_input_names', {'expression': {'refPath': sm}})['returnValue']
        conn(uv, '', sm, info['sm_in'][0])
        conn(c2, '', sm, info['sm_in'][1])
        mul = add(r, 'MaterialExpressionMultiply', -300, 150)
        conn(pc, 'A', mul, 'A')
        conn(sm, '', mul, 'B')
        out(mul, '', 'MP_Opacity')
    else:
        out(pc, 'A', 'MP_Opacity')
    t(M + 'layout_expressions', {'material_or_function': {'refPath': r}})
    t(M + 'recompile', {'material_or_function': {'refPath': r}})
    t(A + 'save_assets', {'asset_paths': [r.split('.')[0]]})
    info['path'] = r
    return info


def run():
    return {'soft': make('M_JamFXSoft', True), 'solid': make('M_JamFXSolid', False)}

