def ref(em,script='',module='',ri=-1,stack=None):
    return {'system':SYS,'emitterName':em,'scriptName':script,'moduleName':module,'rendererIndex':ri,'inputNameStack':stack or []}
def enum_name(path,disp):
    if path not in _EC:
        _EC[path]=json.loads(execute_tool('NiagaraToolsets.NiagaraToolset_Info.UEnum_Info', json.dumps({'enum':{'refPath':path}}))['returnValue'])
    short=path.split('.')[-1]
    for v in _EC[path]['Values']:
        if v['DisplayName']==disp:
            return short+'::'+v['Name']
    raise Exception('enum '+disp+' not in '+path)
def val(spec):
    k=spec[0]
    if k=='f': return {'struct':{'refPath':'/Script/Niagara.NiagaraFloat'},'value':{'value':spec[1]}}
    if k=='i': return {'struct':{'refPath':'/Script/Niagara.NiagaraInt32'},'value':{'value':spec[1]}}
    if k=='b': return {'struct':{'refPath':'/Script/Niagara.NiagaraBool'},'value':{'value':-1 if spec[1] else 0}}
    if k=='c': return {'struct':{'refPath':'/Script/CoreUObject.LinearColor'},'value':{'r':spec[1],'g':spec[2],'b':spec[3],'a':spec[4]}}
    if k=='v3': return {'struct':{'refPath':'/Script/CoreUObject.Vector3f'},'value':{'x':spec[1],'y':spec[2],'z':spec[3]}}
    if k=='v2': return {'struct':{'refPath':'/Script/CoreUObject.Vector2f'},'value':{'x':spec[1],'y':spec[2]}}
    if k=='h': return {'struct':{'refPath':'/Script/NiagaraEditor.NiagaraExt_StackInputData_HlslExpression'},'value':{'hlslExpression':spec[1]}}
    if k=='d': return {'struct':{'refPath':'/Script/NiagaraEditor.NiagaraExt_StackInputData_DynamicInput'},'value':{'dynamicInputAsset':{'refPath':spec[1]}}}
    if k=='e':
        p='/Niagara/Enums/'+spec[1]+'.'+spec[1].split('/')[-1] if not spec[1].startswith('/') else spec[1]
        return {'struct':{'refPath':'/Script/NiagaraEditor.NiagaraExt_StackInputData_Enum'},'value':{'enum':{'refPath':p},'enumName':enum_name(p,spec[2]),'displayName':spec[2]}}
    raise Exception('bad spec')
SC={'ES':'EmitterSpawnScript','EU':'EmitterUpdateScript','PS':'ParticleSpawnScript','PU':'ParticleUpdateScript','SS':'SystemSpawnScript','SU':'SystemUpdateScript'}
ERR=[]
def setin(em,sc,mod,inp,spec):
    stack=inp if isinstance(inp,list) else [inp]
    try:
        call('SetStackInputData',{'stackInputRef':ref(em,SC.get(sc,sc),mod,-1,stack),'inputData':val(spec)})
    except Exception as e:
        ERR.append(em+'/'+mod+'/'+str(stack)+': '+str(e)[:300])
def setmany(em,lst):
    for x in lst: setin(em,x[0],x[1],x[2],x[3])
def uvar(name,spec):
    t={'f':'/Script/Niagara.NiagaraFloat','c':'/Script/CoreUObject.LinearColor'}[spec[0]]
    v=val(spec)
    v['struct']={'refPath':t}
    return {'name':name,'description':'','type':{'classStructOrEnum':{'refPath':t}},'defaultValue':v}
def rset(em,ri,props):
    call('SetRendererData',{'renderer':ref(em,'','',ri),'rendererData':{'propertyValues':json.dumps(props)}})
def status():
    cs=call('GetSystemCompileState',{'system':SYS})
    iss=call('GetStackIssues',{'system':SYS})
    return {'compile':json.dumps(cs)[:1500],'issues':json.dumps(iss)[:3000]}
def save():
    execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths':[SYS['refPath'].split('.')[0]]}))

