import json
S='NiagaraToolsets.NiagaraToolset_System.'
SYS={'refPath':'/Game/FX/NS_JamEmbers.NS_JamEmbers'}
def call(n,a):
    return json.loads(json.dumps(execute_tool(S+n, json.dumps(a))))
def ref(em,script='',module='',ri=-1,stack=None):
    return {'system':SYS,'emitterName':em,'scriptName':script,'moduleName':module,'rendererIndex':ri,'inputNameStack':stack or []}
def short(v):
    st=v.get('struct',{}).get('refPath','').split('.')[-1]
    x=v.get('value',{})
    if 'Enum' in st: return 'E:'+x.get('displayName','')
    if 'Unsupported' in st: return None
    if 'DynamicInput' in st: return 'D:'+x.get('dynamicInputAsset',{}).get('refPath','').split('.')[-1]
    if 'Linked' in st: return 'L:'+x.get('linkedVariable',{}).get('name','')
    if 'Hlsl' in st: return 'H:'+x.get('hlslExpression','')
    return json.dumps(x)
def run():
    call('CreateNiagaraSystem',{'assetName':'NS_JamEmbers','assetPath':'/Game/FX','templateSystem':{'refPath':'/Niagara/DefaultAssets/Templates/Systems/RadialBurst.RadialBurst'}})
    for e in ['RibbonTrailFollower','Ribbon_Trail_Leader','OmnidirectionalBurst']:
        call('RemoveEmitter',{'emitterToRemove':ref(e)})
    call('AddEmitter',{'system':SYS,'templateEmitter':{'refPath':'/Niagara/DefaultAssets/Templates/Emitters/HangingParticulates.HangingParticulates'},'emitterName':'Embers'})
    t=call('GetEmitterTopology',{'emitterRef':ref('Embers')})['returnValue']
    vis={}
    for sc in ['emitterUpdateScript','particleSpawnScript','particleUpdateScript']:
        for m in t[sc]['modules']:
            vis[m['moduleName']]=set(i['name'] for i in m['inputs'] if i['bIsVisible'])
    out=[]
    v=call('GetEmitterInputValues',{'emitterRef':ref('Embers')})['returnValue']
    mods=v if isinstance(v,list) else v.get('modules',[])
    for m in mods:
        s=m['moduleName']+': '
        for i in m['inputs']:
            if i['name'] in vis.get(m['moduleName'],()):
                sv=short(i['value'])
                if sv is not None: s+=i['name']+'='+sv+'; '
        out.append(s[:1000])
    rd=json.loads(call('GetRendererData',{'rendererRef':ref('Embers','','',0)})['returnValue']['propertyValues'])
    out.append(str(rd.get('Material')))
    return {'o':out}

